// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata tos, uint256 v) public {
        vm.assume(tos.length > 0);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }
        bool success = c.transfer(from, caddress, tos, v);
        assertTrue(success);
    }
}
